from __future__ import annotations

import json
from pathlib import Path


def read(path: str) -> str:
    return Path(path).read_text(encoding="utf-8")


def write(path: str, text: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding="utf-8")


def write_json(path: str, payload: object) -> None:
    write(path, json.dumps(payload, ensure_ascii=False, indent=2) + "\n")


def replace_once(path: str, old: str, new: str) -> None:
    text = read(path)
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected one occurrence, got {count}: {old[:140]!r}")
    write(path, text.replace(old, new, 1))


def insert_before(path: str, marker: str, content: str) -> None:
    text = read(path)
    if text.count(marker) != 1:
        raise RuntimeError(f"{path}: insertion marker count != 1: {marker[:100]!r}")
    write(path, text.replace(marker, content + marker, 1))


