write("tests/test_editorial_runtime_contract.py", '''from __future__ import annotations\n\nimport unittest\n\nfrom pydantic import ValidationError\n\nfrom app.agent import EpisodePlan, editorial_director_agent, writer_agent\n\n\ndef valid_plan() -> dict:\n    return {\n        "topic_signature": "criterio humano bajo automatizacion",\n        "narrative_lens": "cognicion",\n        "novelty_angle": "Investiga el cierre de tareas, no la capacidad bruta.",\n        "historical_mirror": "Una herramienta histórica cambia qué consideramos saber.",\n        "evidence_strategy": "Casos actuales complican una creencia inicial.",\n        "central_question": "¿Cuándo deja de ser ayuda y empieza a ser delegación?",\n        "thesis": "Al principio parece que el problema es verificar a la máquina.",\n        "hook": "Una marca verde dice que todo terminó. ¿Pero quién decidió eso?",\n        "target_duration_minutes": 10,\n        "narrative_arc": {\n            "opening_belief": "Verificar mejor parece suficiente.",\n            "central_mystery": "¿Qué significa realmente terminar una tarea?",\n            "concrete_scene": "Un agente cierra un incidente de madrugada sin intervención.",\n            "first_reveal": "La verificación también puede automatizarse.",\n            "complication": "El humano puede terminar confiando en el proceso de verificación.",\n            "narrative_turn": "El problema pasa de errores de IA a criterio delegado.",\n            "second_reveal": "La decisión de dar algo por terminado es también trabajo cognitivo.",\n            "evolved_thesis": "Automatizamos no solo tareas, sino el momento en que decidimos que merecen considerarse terminadas.",\n            "recurring_motif": "Ya quedó.",\n            "emotional_peak": "Una persona asume una decisión que nadie revisó conscientemente.",\n            "final_payoff": "Al final, ya quedó deja de ser una confirmación y se vuelve una pregunta.",\n        },\n        "stories": [{\n            "selected_news_index": 1, "role": "anchor", "argument_role": "evidence",\n            "estimated_minutes": 4, "narrative_function": "volver concreto el misterio",\n        }],\n        "final_synthesis": "La automatización mueve el lugar donde ejercemos criterio.",\n        "closing_question": "¿Qué significa para ti que algo ya quedó?",\n    }\n\n\nclass EditorialRuntimeContractTests(unittest.TestCase):\n    def test_director_and_writer_runtime_prompts_contain_full_dramaturgy(self) -> None:\n        director = editorial_director_agent.instruction.lower()\n        writer = writer_agent.instruction.lower()\n        fields = (\n            "opening_belief", "central_mystery", "concrete_scene", "first_reveal",\n            "complication", "narrative_turn", "second_reveal", "evolved_thesis",\n            "recurring_motif", "emotional_peak", "final_payoff",\n        )\n        for field in fields:\n            self.assertIn(field, director)\n            self.assertIn(field, writer)\n\n    def test_episode_plan_requires_complete_narrative_arc(self) -> None:\n        plan = valid_plan()\n        del plan["narrative_arc"]["narrative_turn"]\n        with self.assertRaises(ValidationError):\n            EpisodePlan.model_validate(plan)\n\n    def test_episode_plan_rejects_non_evolving_thesis(self) -> None:\n        plan = valid_plan()\n        plan["narrative_arc"]["evolved_thesis"] = plan["thesis"]\n        with self.assertRaises(ValidationError):\n            EpisodePlan.model_validate(plan)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''')

write("tests/test_editorial_calibration.py", '''from __future__ import annotations\n\nimport unittest\nfrom pathlib import Path\n\nfrom pipeline.editorial_calibration import build_calibration_report\n\n\nclass EditorialCalibrationTests(unittest.TestCase):\n    def test_real_baseline_exposes_judge_human_disagreement_without_premature_policy(self) -> None:\n        report = build_calibration_report(Path("evals/editorial/cases.json"))\n        self.assertEqual(report["case_count"], 3)\n        self.assertEqual(report["human_publishable_count"], 0)\n        self.assertEqual(report["human_reject_count"], 3)\n        self.assertEqual(report["judge_metrics"]["seo"]["false_accept_count"], 3)\n        self.assertEqual(report["judge_metrics"]["attention"]["false_accept_count"], 3)\n        self.assertEqual(report["judge_metrics"]["voice"]["false_accept_count"], 0)\n        self.assertFalse(report["calibration_readiness"]["ready_for_dimension_thresholds"])\n        self.assertFalse(report["calibration_readiness"]["ready_for_judge_model_diversification_decision"])\n        self.assertFalse(report["policy"]["voice_dimension_thresholds_active"])\n\n\nif __name__ == "__main__":\n    unittest.main()\n''')

write("tests/test_e2e_failure_paths.py", '''from __future__ import annotations\n\nimport json\nimport os\nimport tempfile\nimport unittest\nfrom dataclasses import replace\nfrom datetime import date\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nfrom pipeline import run as pipeline_run\n\n\ndef plan_payload() -> dict:\n    return {\n        "topic_signature": "delegacion de criterio humano",\n        "narrative_lens": "cognicion",\n        "novelty_angle": "Cambia el foco desde capacidad a cierre de decisiones.",\n        "historical_mirror": "Espejo histórico verificable.",\n        "evidence_strategy": "Un caso prueba y otro complica.",\n        "central_question": "¿Qué delegamos cuando dejamos que el sistema cierre el ciclo?",\n        "thesis": "Parece un problema de verificación.",\n        "hook": "El sistema dice que ya terminó.",\n        "target_duration_minutes": 7.0,\n        "narrative_arc": {\n            "opening_belief": "Verificar parece suficiente.",\n            "central_mystery": "¿Quién decide que algo terminó?",\n            "concrete_scene": "Un agente resuelve un incidente solo.",\n            "first_reveal": "Verificar también se automatiza.",\n            "complication": "La supervisión humana puede volverse ritual.",\n            "narrative_turn": "El problema se mueve hacia el criterio delegado.",\n            "second_reveal": "Cerrar una tarea es una decisión.",\n            "evolved_thesis": "Automatizamos el momento en que decidimos que una tarea merece considerarse terminada.",\n            "recurring_motif": "Ya quedó.",\n            "emotional_peak": "Alguien asume una decisión que nadie revisó realmente.",\n            "final_payoff": "Ya quedó termina siendo una pregunta, no una confirmación.",\n        },\n        "stories": [{\n            "selected_news_index": 1, "role": "anchor", "argument_role": "evidence",\n            "estimated_minutes": 4, "narrative_function": "hacer tangible el problema",\n        }],\n        "final_synthesis": "La automatización desplaza el lugar del criterio.",\n        "closing_question": "¿Qué no delegarías?",\n    }\n\n\ndef marked_script() -> str:\n    return (\n        "<!--SECTION:opening-->" + " ".join(["inicio"] * 250) +\n        " <!--SECTION:story:1-->" + " ".join(["desarrollo"] * 600) +\n        " <!--SECTION:synthesis-->" + " ".join(["cierre"] * 200)\n    )\n\n\ndef write_news(news: Path) -> None:\n    (news / "2026-08-20.txt").write_text(\n        "# Noticias\\n\\n## 1. Caso\\nFecha: 2026-08-20\\nFuente: Primaria\\nEnlace: https://example.com/case\\nCategoría: agentes\\nResumen: Caso verificable\\nPor qué importa: Impacto\\n",\n        encoding="utf-8",\n    )\n\n\nclass E2EFailurePathTests(unittest.IsolatedAsyncioTestCase):\n    async def test_voice_failure_stops_before_multimedia(self) -> None:\n        steps: list[str] = []\n        async def fake(agent, state, prompt, *, step, trace, iteration=None):\n            steps.append(step)\n            if step == "select_news":\n                return {"selected_news": {"items": [{"news_id": "2026-08-20:1", "selection_reason": "relevante"}], "discarded_duplicates": [], "selection_notes": []}}\n            if step == "plan_episode":\n                return {"episode_plan": plan_payload()}\n            if step == "write_script":\n                return {"draft_script": marked_script()}\n            if step == "editorial_judge":\n                return {"review": {"score": 9.2, "approved": True, "factuality_risk": "low", "strengths": [], "problems": [], "improvements": []}}\n            if step in {"seo_judge", "attention_judge"}:\n                key = "seo_review" if step == "seo_judge" else "attention_review"\n                return {key: {"score": 9.0, "approved": True, "strengths": [], "problems": [], "improvements": []}}\n            if step == "voice_judge":\n                return {"voice_review": {"score": 7.0, "approved": False, "voice_fidelity": 7, "intellectual_depth": 7, "human_relevance": 7, "analogy_quality": 7, "ai_smell_risk": "medium", "strengths": [], "problems": ["flat"], "improvements": []}}\n            self.fail(f"Unexpected step {step}")\n\n        with tempfile.TemporaryDirectory() as tmp:\n            root = Path(tmp); news = root/"news"; scripts=root/"scripts"; media=root/"media"; history=root/"history"\n            news.mkdir(); history.mkdir(); write_news(news)\n            config = replace(pipeline_run.CONFIG, max_refinement_iterations=1)\n            with patch.dict(os.environ, {"OPENAI_API_KEY": "test"}), patch.object(pipeline_run, "CONFIG", config), patch.object(pipeline_run, "run_agent", side_effect=fake):\n                out = await pipeline_run.build(target_date=date(2026,8,21), news_dir=news, scripts_root=scripts, multimedia_root=media, history_scripts_root=history, max_media_downloads=0, download_multimedia=False)\n            state = json.loads((out/"run_state.json").read_text())\n            self.assertEqual(state["status"], "script_not_approved")\n            self.assertNotIn("plan_multimedia", steps)\n\n    async def test_exhausted_novelty_replans_stop_before_writer(self) -> None:\n        steps: list[str] = []\n        async def fake(agent, state, prompt, *, step, trace, iteration=None):\n            steps.append(step)\n            if step == "select_news":\n                return {"selected_news": {"items": [{"news_id": "2026-08-20:1", "selection_reason": "relevante"}], "discarded_duplicates": [], "selection_notes": []}}\n            if step in {"plan_episode", "replan_episode_novelty"}:\n                return {"episode_plan": plan_payload()}\n            self.fail(f"Unexpected step {step}")\n\n        with tempfile.TemporaryDirectory() as tmp:\n            root = Path(tmp); news = root/"news"; scripts=root/"scripts"; media=root/"media"; history=root/"history"\n            news.mkdir(); history.mkdir(); write_news(news)\n            old = history/"2026-08-20"; old.mkdir()\n            (old/"reviews.json").write_text(json.dumps({"approved_for_multimedia": True}))\n            (old/"episode_plan.json").write_text(json.dumps(plan_payload()))\n            (old/"script.txt").write_text("ensayo previo")\n            config = replace(pipeline_run.CONFIG, max_novelty_replans=1)\n            duplicate = {"similarity": 0.95, "episode_date": "2026-08-20", "topic_signature": "same"}\n            with patch.dict(os.environ, {"OPENAI_API_KEY": "test"}), patch.object(pipeline_run, "CONFIG", config), patch.object(pipeline_run, "run_agent", side_effect=fake), patch.object(pipeline_run, "nearest_essay_similarity", return_value=duplicate):\n                out = await pipeline_run.build(target_date=date(2026,8,21), news_dir=news, scripts_root=scripts, multimedia_root=media, history_scripts_root=history, max_media_downloads=0, download_multimedia=False)\n            state = json.loads((out/"run_state.json").read_text())\n            self.assertEqual(state["status"], "no_novel_essay_angle")\n            self.assertEqual(steps.count("replan_episode_novelty"), 1)\n            self.assertNotIn("write_script", steps)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''')

write("tests/test_media_relevance.py", '''from __future__ import annotations\n\nimport unittest\n\nfrom pipeline.media import media_relevance_score, select_best_candidate\n\n\nclass MediaRelevanceTests(unittest.TestCase):\n    def test_security_dashboard_beats_decorative_scrabble(self) -> None:\n        query = "cybersecurity monitoring dashboard"\n        candidates = [\n            {"candidate_text": "Scrabble tiles spelling SECURITY", "provider": "pexels"},\n            {"candidate_text": "Cyber security monitoring dashboard with incident alerts", "provider": "wikimedia_commons"},\n        ]\n        best = select_best_candidate(query, candidates)\n        self.assertIsNotNone(best)\n        self.assertIn("dashboard", best["candidate_text"].lower())\n\n    def test_unrelated_stock_photo_falls_below_relevant_diagram(self) -> None:\n        query = "software patching workflow diagram"\n        relevant = media_relevance_score(query, "software update patch workflow diagram showing deployment stages")\n        generic = media_relevance_score(query, "businessman standing at whiteboard in office")\n        self.assertGreater(relevant, generic)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''')

write("tests/test_credits.py", '''from __future__ import annotations\n\nimport tempfile\nimport unittest\nfrom pathlib import Path\n\nfrom pipeline.credits import build_credits, write_credits\nfrom pipeline.licenses import assess_license\n\n\nclass CreditsTests(unittest.TestCase):\n    def test_cc_by_asset_generates_attribution_credit(self) -> None:\n        manifest = [{"shot_number": 1, "file": "assets/a.jpg", "provider": "wikimedia_commons", "creator": "Ada", "license": "CC BY 4.0", "source_url": "https://commons.wikimedia.org/x"}]\n        payload = build_credits(manifest)\n        self.assertTrue(payload["all_assets_license_valid"])\n        self.assertEqual(payload["attribution_required_count"], 1)\n        with tempfile.TemporaryDirectory() as tmp:\n            md, js = write_credits(manifest, Path(tmp))\n            self.assertIn("Ada", md.read_text())\n            self.assertTrue(js.exists())\n\n    def test_noncommercial_and_unknown_licenses_are_rejected(self) -> None:\n        self.assertFalse(assess_license("wikimedia_commons", "CC BY-NC 4.0")["allowed"])\n        self.assertFalse(assess_license("wikimedia_commons", "All Rights Reserved")["allowed"])\n        with self.assertRaises(ValueError):\n            build_credits([{"file": "x.jpg", "provider": "wikimedia_commons", "license": "CC BY-NC 4.0"}])\n\n\nif __name__ == "__main__":\n    unittest.main()\n''')

write("tests/test_configuration_contract.py", '''from __future__ import annotations\n\nimport unittest\nfrom pathlib import Path\n\nfrom pipeline.core import PIPELINE_ENV_DEFAULTS\n\n\nclass ConfigurationContractTests(unittest.TestCase):\n    def test_every_pipeline_env_is_exposed_to_build_and_report(self) -> None:\n        workflow = Path(".github/workflows/build-video-kit.yml").read_text(encoding="utf-8")\n        for name in PIPELINE_ENV_DEFAULTS:\n            self.assertGreaterEqual(workflow.count(f"{name}:"), 2, name)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''')

write("tests/test_dependency_lock.py", '''from __future__ import annotations\n\nimport unittest\nfrom pathlib import Path\n\n\nclass DependencyLockTests(unittest.TestCase):\n    def test_runtime_lock_pins_critical_direct_dependencies(self) -> None:\n        lock = Path("requirements.lock").read_text(encoding="utf-8").lower()\n        for package in ("google-adk", "google-genai", "litellm", "openai", "pydantic", "requests", "pillow"):\n            self.assertRegex(lock, rf"(?m)^{package}==[^\\s]+")\n        self.assertIn("google-adk==2.6.3", lock)\n\n    def test_ci_and_production_install_with_lock_constraints(self) -> None:\n        ci = Path(".github/workflows/ci.yml").read_text(encoding="utf-8")\n        prod = Path(".github/workflows/build-video-kit.yml").read_text(encoding="utf-8")\n        self.assertIn("pip install -c requirements.lock .", ci)\n        self.assertIn("pip install -c requirements.lock .", prod)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''')

write("tests/test_legacy_history.py", '''from __future__ import annotations\n\nimport json\nimport tempfile\nimport unittest\nfrom datetime import date\nfrom pathlib import Path\n\nfrom pipeline.run import load_essay_history\n\n\nclass LegacyHistoryTests(unittest.TestCase):\n    def test_repository_legacy_episode_is_explicitly_excluded(self) -> None:\n        marker = json.loads(Path("scripts/2026-08-21/legacy.json").read_text(encoding="utf-8"))\n        self.assertTrue(marker["legacy"])\n        self.assertTrue(marker["exclude_from_essay_history"])\n        self.assertTrue(marker["exclude_from_voice_dna"])\n\n    def test_legacy_episode_does_not_enter_essay_memory(self) -> None:\n        with tempfile.TemporaryDirectory() as tmp:\n            root = Path(tmp)\n            legacy = root/"2026-08-20"; legacy.mkdir()\n            (legacy/"reviews.json").write_text(json.dumps({"approved_for_multimedia": True}))\n            (legacy/"legacy.json").write_text(json.dumps({"exclude_from_essay_history": True}))\n            (legacy/"script.txt").write_text("HISTORIA 1 noticia 1 Segunda historia")\n            modern = root/"2026-08-19"; modern.mkdir()\n            (modern/"reviews.json").write_text(json.dumps({"approved_for_multimedia": True}))\n            (modern/"episode_plan.json").write_text(json.dumps({"topic_signature": "educacion y criterio", "central_question": "q", "thesis": "t", "narrative_lens": "education", "hook": "h"}))\n            (modern/"script.txt").write_text("ensayo moderno")\n            essays = load_essay_history(root, date(2026,8,21), 120, 12)\n            self.assertEqual(len(essays), 1)\n            self.assertEqual(essays[0]["episode_date"], "2026-08-19")\n\n\nif __name__ == "__main__":\n    unittest.main()\n''')

